-- Base de datos de Productos de Botillería (Chile)
-- Generado con datos reales de retail y botillería
-- Incluye EAN-13, SKU, Precios CLP, Categorías, Fotos (local y remota) e Impuestos ILA/SII

CREATE TABLE IF NOT EXISTS botilleria_categorias (
    id INT PRIMARY KEY AUTO_INCREMENT,
    nombre VARCHAR(100) NOT NULL,
    slug VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS botilleria_productos (
    id INT PRIMARY KEY AUTO_INCREMENT,
    sku VARCHAR(64) NOT NULL UNIQUE,
    codigo_barra VARCHAR(64) NOT NULL,
    nombre VARCHAR(255) NOT NULL,
    categoria_id INT NOT NULL,
    marca VARCHAR(100) NULL,
    precio DECIMAL(14,0) NOT NULL,
    formato VARCHAR(50) NULL,
    afecto_iva TINYINT(1) DEFAULT 1,
    verificar_edad TINYINT(1) DEFAULT 0,
    impuesto_ila_pct DECIMAL(5,2) DEFAULT 0.00,
    impuesto_ila_codigo VARCHAR(50) NULL,
    imagen_local VARCHAR(255) NULL,
    imagen_url VARCHAR(500) NULL,
    KEY idx_codigo_barra (codigo_barra),
    KEY idx_nombre (nombre),
    FOREIGN KEY (categoria_id) REFERENCES botilleria_categorias(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

